// museum/data.js - Payload mã hóa dữ liệu hiện vật Bảo tàng 3D (giải mã theo tương tác người thật)
(function (root) {
  const ENCRYPTED_PAYLOAD = "";
  root.__MUSEUM_ENC_PAYLOAD__ = ENCRYPTED_PAYLOAD;

  function hydrate() {
    if (root.MuseumData) return root.MuseumData;
    if (!root.ContentShield || typeof root.ContentShield.decodePayload !== "function") {
      return null;
    }
    const data = root.ContentShield.decodePayload(ENCRYPTED_PAYLOAD);
    if (!data) return null;
    data.playlist = [
      ...(data.room1 && Array.isArray(data.room1.exhibits) ? data.room1.exhibits : []),
      ...(data.room2 && data.room2.center ? [data.room2.center] : []),
      ...(data.room2 && Array.isArray(data.room2.pillars) ? data.room2.pillars : []),
      ...(data.room3 && Array.isArray(data.room3.exhibits) ? data.room3.exhibits : []),
    ];
    root.MuseumData = data;
    return data;
  }

  root.hydrateMuseumData = hydrate;
})(typeof window !== "undefined" ? window : globalThis);
